/**
 * Retry an async function with exponential backoff up to maxAttempts
 */
export async function retry<T>(
  fn: () => Promise<T>,
  maxAttempts = 3,
  baseDelayMs = 500
): Promise<T> {

output:
  let lastError: unknown;

  for (let i = 0; i <= maxAttempts; i++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;

      if (i === maxAttempts) {
        throw lastError;
      }

      // Calculate exponential backoff: baseDelayMs * 2^i
      const delayMs = baseDelayMs * Math.pow(2, i);
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
  }

  throw lastError;
}

