interface FormState {
  values: Record<string, string>
  errors: Record<string, string>
  isSubmitting: boolean
}

type Action =
  | { type: 'set_field'; field: string; value: string }
  | { type: 'set_errors'; errors: Record<string, string> }
  | { type: 'submit_start' }
  | { type: 'submit_end' }

export function useFormReducer(initial: Record<string, string>) {

output:
  const [state, dispatch] = useReducer(
    (state: FormState, action: Action): FormState => {
      switch (action.type) {
        case 'set_field':
          return {
            ...state,
            values: { ...state.values, [action.field]: action.value },
          }
        case 'set_errors':
          return {
            ...state,
            errors: { ...state.errors, [action.field]: action.value },
          }
        case 'submit_start':
          return { ...state, isSubmitting: true }
        case 'submit_end':
          return { ...state, isSubmitting: false }
        default:
          return state
      }
    },
    {
      values: { ...initial },
      errors: {},
      isSubmitting: false,
    }
  )

  return {
    ...state,
    dispatch,
  }
}
